package com.trombokendu.chronos.concurrency;import com.trombokendu.chronos.domain.*;import java.util.*;import java.util.concurrent.*;import java.util.function.*;public final class EventBus{private final Map<Class<?>,CopyOnWriteArrayList<Consumer<?>>> listeners=new ConcurrentHashMap<>();public <T extends LedgerEvent>void subscribe(Class<T> type,Consumer<T> consumer){listeners.computeIfAbsent(type,k->new CopyOnWriteArrayList<>()).add(consumer);} @SuppressWarnings("unchecked") public void publish(LedgerEvent e){listeners.forEach((k,v)->{if(k.isInstance(e))for(Consumer<?> c:v)((Consumer<LedgerEvent>)c).accept(e);});}}
